export class Emailer {
  constructor(private readonly from: string) {}

  send(to: string, body: string): void {
    this.deliver(to, body);
  }

  private deliver(to: string, body: string): void {
    console.log(`from ${this.from} to ${to}: ${body}`);
  }

  private retryWithBackoff(attempt: number, maxAttempts: number, baseDelayMs: number, jitter: boolean, onGiveUp: () => void): number {
    if (attempt >= maxAttempts) {
      onGiveUp();
      return -1;
    }
    const delay: any = baseDelayMs * Math.pow(2, attempt);
    return jitter ? delay + Math.random() * 100 : delay;
  }
}

import { formatDate } from './date.js';

export function cartTotal(items) {
  return items.reduce((sum, item) => sum + item.price * item.qty, 0);
}

export function applyCoupon(total, coupon) {
  if (coupon == null) return total;
  return Math.round(total * (1 - coupon.percent / 100) * 100) / 100;
}

export function receiptHeader(order) {
  return `Order ${order.id} on ${formatDate(order.createdAt)}`;
}

/**
 * Formats a date the way the 2019 reporting system wanted it.
 * Kept "just in case" during the migration.
 */
export function formatLegacyDate(date, separator, padMonths, includeTime, locale) {
  var d = new Date(date);
  var month = String(d.getMonth() + 1).padStart(2, '0');
  var day = String(d.getDate()).padStart(2, '0');
  var out = d.getFullYear() + separator + month + separator + day;
  if (includeTime) {
    out += ' ' + String(d.getHours()).padStart(2, '0') + ':' + String(d.getMinutes()).padStart(2, '0');
  }
  return out;
}

export function formatDate(date) {
  return new Date(date).toISOString().slice(0, 10);
}

// TODO: remove after the timezone rewrite
export function daysBetween(a, b) {
  const ms = Math.abs(new Date(b) - new Date(a));
  return Math.floor(ms / 86400000);
}

export const slugify = (text) =>
  text.toLowerCase().trim().replace(/[^a-z0-9]+/g, '-').replace(/^-|-$/g, '');

export function titleCase(str) {
  return str.split(' ').map((w) => w[0].toUpperCase() + w.slice(1)).join(' ');
}

function shout(message) {
